def a_estados_nuevos(apps, schema_editor):
    Sesion = apps.get_model("sesiones", "Sesion")
    Sesion.objects.filter(estado="SIN_INICIAR").update(estado="PROGRAMADA")
    # Las que ya empezaron no tenían hora real de inicio: se toma la programada.
    for sesion in Sesion.objects.filter(estado__in=["EN_CURSO", "FINALIZADA"], iniciada_en__isnull=True):
        sesion.iniciada_en = sesion.inicio
        sesion.save(update_fields=["iniciada_en"])


